<!-- Skip Link -->
<a href="#main-content" class="skip-link">Skip to main content</a>

<!-- ===== Header ===== -->
<header class="header" id="header" role="banner">
  <div class="container">
    <a href="/" class="logo" aria-label="MedBook Home">
      <div class="logo-icon" aria-hidden="true">
        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10Z"/><path d="M8 14s1.5 2 4 2 4-2 4-2"/><path d="M9 9h.01"/><path d="M15 9h.01"/><path d="M8 12h8"/></svg>
      </div>
      MedBook
    </a>
    <nav class="nav-desktop" aria-label="Main navigation">
      <a href="#specialties">Browse</a>
      <a href="#how-it-works">Help</a>
    </nav>
    <div class="nav-cta">
      <a href="#" class="btn btn-outline">Log In</a>
      <a href="#" class="btn btn-primary">Sign Up</a>
    </div>
    <button class="hamburger" id="hamburger" aria-label="Toggle navigation menu" aria-expanded="false">
      <span></span>
    </button>
  </div>
</header>

<!-- ===== Mobile Nav ===== -->
<nav class="mobile-nav" id="mobileNav" aria-label="Mobile navigation">
  <a href="#specialties">Browse Specialties</a>
  <a href="#how-it-works">How It Works</a>
  <a href="#">Help Center</a>
  <a href="#" class="btn btn-outline" style="display:block;text-align:center">Log In</a>
  <a href="#" class="btn btn-primary" style="display:block;text-align:center">Sign Up</a>
</nav>
<div class="mobile-overlay" id="mobileOverlay"></div>

<!-- ===== Hero ===== -->
<main id="main-content">
<section class="hero" id="hero" aria-labelledby="hero-heading">
  <div class="container">
    <h1 id="hero-heading" class="animate-in">Find and book the care you need</h1>
    <p class="hero-subtitle animate-in delay-1">Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day. It's that easy, and always free.</p>

    <div class="search-card animate-in delay-2" role="search" aria-label="Find a doctor">
      <div class="search-row">
        <div class="autocomplete-wrap search-field">
          <label for="searchQuery" class="field-label">Condition, specialty, or doctor</label>
          <input type="text" id="searchQuery" placeholder="Search by condition, specialty, or doctor name" autocomplete="off" aria-autocomplete="list" aria-controls="autocomplete-list" role="combobox" aria-expanded="false">
          <div class="autocomplete-dropdown" id="autocomplete-list" role="listbox" aria-label="Search suggestions"></div>
        </div>
        <div class="search-field">
          <label for="searchLocation" class="field-label">Location</label>
          <input type="text" id="searchLocation" placeholder="City, state, or zip code">
        </div>
        <div class="search-field">
          <label for="searchInsurance" class="field-label">Insurance</label>
