    { name:'Cardiologist', detail:'Heart health, blood pressure', icon:'&#10084;&#65039;' },
    { name:'Pediatrician', detail:'Child health, vaccinations', icon:'&#128118;' },
    { name:'OB-GYN', detail:'Women\'s health, pregnancy', icon:'&#129328;' },
    { name:'ENT Specialist', detail:'Ear, nose, throat conditions', icon:'&#128066;' },
    { name:'Dr. Sarah Chen', detail:'Internal Medicine, New York', icon:'&#128105;&#8205;&#9877;&#65039;' },
