    { name:'Back Pain', detail:'Spine specialists, chiropractors', icon:'&#129504;' },
    { name:'Allergies', detail:'Allergists, immunologists', icon:'&#127807;' },
    { name:'Physical Therapy', detail:'Rehabilitation, sports recovery', icon:'&#127947;' }
  ];

  // ----- DOM Elements -----
  const searchInput = document.getElementById('searchQuery');
  const dropdown = document.getElementById('autocomplete-list');
  const searchBtn = document.getElementById('searchBtn');
  const header = document.getElementById('header');
  const hamburger = document.getElementById('hamburger');
  const mobileNav = document.getElementById('mobileNav');
  const mobileOverlay = document.getElementById('mobileOverlay');

  // ----- Autocomplete -----
  let highlightedIndex = -1;

  function filterSuggestions(query){
    if(!query || query.trim().length < 1) return [];
    const q = query.toLowerCase().trim();
    return suggestions.filter(s =>
      s.name.toLowerCase().includes(q) || s.detail.toLowerCase().includes(q)
    ).slice(0, 8);
  }

  function renderDropdown(items){
    dropdown.innerHTML = '';
    if(items.length === 0){
      dropdown.innerHTML = '<div class="no-results">No matching doctors or specialties found</div>';
    }else{
      items.forEach((item,i) => {
        const div = document.createElement('div');
        div.className = 'suggestion' + (i === highlightedIndex ? ' highlighted' : '');
        div.setAttribute('role','option');
        div.setAttribute('aria-selected', i === highlightedIndex ? 'true' : 'false');
        div.innerHTML = '<span class="suggestion-icon" aria-hidden="true">' + item.icon + '</span>' +
          '<span class="suggestion-text"><span class="suggestion-name">' + escHtml(item.name) + '</span>' +
          '<span class="suggestion-detail">' + escHtml(item.detail) + '</span></span>';
        div.addEventListener('click', function(){ selectSuggestion(item); });
        div.addEventListener('mousedown', function(e){ e.preventDefault(); });
        dropdown.appendChild(div);
      });
    }
    dropdown.classList.add('show');
    searchInput.setAttribute('aria-expanded','true');
  }

  function closeDropdown(){
    dropdown.classList.remove('show');
    highlightedIndex = -1;
    searchInput.setAttribute('aria-expanded','false');
  }

  function selectSuggestion(item){
    searchInput.value = item.name;
    closeDropdown();
    doSearch();
